type BucketStore struct {
	logger log.Logger
	// ... other fields
}

func (s *BucketStore) SyncBlocks(ctx context.Context) error {
	// existing method implementation
}

type BucketStores struct {
	stores map[string]*BucketStore
}

func (u *BucketStores) SyncBlocks(ctx context.Context) error {
	return u.syncUsersBlocksWithRetries(ctx, func(ctx context.Context, store *BucketStore) error {
		return store.SyncBlocks(ctx)
	})
}

type mockBucketStore struct {
	syncBlocksCalled bool
}

func (m *mockBucketStore) SyncBlocks(ctx context.Context) error {
	m.syncBlocksCalled = true
	return nil
}

